package com.javatpoint.servlets;
import java.io.IOException;import javax.servlet.ServletException;import javax.servlet.annotation.WebServlet;import javax.servlet.http.*;import com.javatpoint.beans.BookBean;import com.javatpoint.dao.BookDao;import com.javatpoint.util.AuthUtil;
@WebServlet("/AddBook") public class AddBook extends HttpServlet{protected void doPost(HttpServletRequest req,HttpServletResponse res)throws ServletException,IOException{if(!AuthUtil.requireLibrarian(req,res))return;try{int q=Integer.parseInt(req.getParameter("quantity"));BookBean b=new BookBean(req.getParameter("callno"),req.getParameter("name"),req.getParameter("author"),req.getParameter("publisher"),q);if(BookDao.save(b)>0)res.sendRedirect("ViewBook");else{res.setContentType("text/html;charset=UTF-8");res.getWriter().print("<link rel='stylesheet' href='app.css'><div class='page'><div class='card form-card'><h2>Could not save book</h2><p class='muted'>Check the details and make sure the call number is unique.</p><a href='AddBookForm'>Back</a></div></div>");}}catch(NumberFormatException e){res.sendError(400,"Quantity must be a positive number.");}}}